from fastcore.utils import *
from .core import *
from .core import _tmux
import uuid

# %% ../nbs/01_bg.ipynb #ff5a0a57
SESSION_PREFIX = 'fastmux-'

def start_session(
    sid=None,    # Session name; default: a generated `fastmux-`-prefixed name
    cmd=None,    # Command to run (str or argv list); default: the user's shell
    cwd=None,    # Working directory
    env=None,    # Extra environment vars as a dict
    width=None,  # Terminal width in columns
    height=None, # Terminal height in rows
):
    "The session named `sid`, created detached (managed, with `remain` set) if it doesn't exist"
    if sid is None: sid = f'{SESSION_PREFIX}{uuid.uuid4().hex[:10]}'
    try: return tmux(sid)
    except TmuxError: pass
    s = new_session(name=sid, width=width, height=height, cwd=cwd, env=env, remain=True)
    p = Pane.fetch(s.id)
    _tmux('set-option','-t',s.id,'@fastmux_pane_id',p.id)
    _tmux('set-option','-w','-t',p.id,'remain-on-exit-format','')
    if cmd is not None:
        args = ['respawn-pane','-k','-t',p.id]
        if cwd is not None: args += ['-c',os.fspath(cwd)]
        args += [x for k,v in (env or {}).items() for x in ('-e',f'{k}={v}')]
        args += [cmd] if isinstance(cmd,str) else list(cmd)
        _tmux(*args)
    return s

# %% ../nbs/01_bg.ipynb #25b4280b
def pane(sid=None):
    "The pane `sid` addresses: a session name (its managed pane), a `%pane_id`, a `Session` or `Pane` handle, or None for the current pane"
    if isinstance(sid, Pane): return sid
    if isinstance(sid, Session): sid = sid.name
    if sid is None: return current_pane()
    if sid.startswith('%'): return Pane.fetch(sid)
    _tmux('has-session','-t',f'={sid}')
    pid = _tmux('show-options','-qv','-t',f'={sid}','@fastmux_pane_id')
    return Pane.fetch(pid or f'={sid}:')  # exact session pin: a window sharing the name can never shadow it

# %% ../nbs/01_bg.ipynb #26bfe98f
def send(sid=None, chars='', wait_ms=0, interval_ms=50, lines=80, screen=False, styles=False, until=None, settle_ms=0):
    "Paste `chars` into `sid`'s pane literally, then `poll`"
    return pane(sid).send(chars, wait_ms, interval_ms, lines, screen, styles, until, settle_ms)

def send_keys(sid=None, *keys, wait_ms=0, interval_ms=50, lines=80, screen=False, styles=False, until=None, settle_ms=0):
    "Send tmux key names to `sid`'s pane, then `poll`"
    return pane(sid).send_keys(*keys, wait_ms=wait_ms, interval_ms=interval_ms, lines=lines, screen=screen, styles=styles,
                               until=until, settle_ms=settle_ms)

def interrupt(sid=None, wait_ms=0, interval_ms=50, lines=80, screen=False, styles=False, until=None, settle_ms=0):
    "Send `Ctrl-C` to `sid`'s pane, then `poll`"
    return pane(sid).interrupt(wait_ms, interval_ms, lines, screen, styles, until, settle_ms)

def poll(sid=None, wait_ms=0, interval_ms=50, lines=80, screen=False, styles=False, until=None, settle_ms=0):
    "Wait for `sid`'s pane to differ from its last-seen state (or to match `until`, or to settle), then capture the last `lines` (the viewport instead with `screen=True`)"
    return pane(sid).poll(wait_ms, interval_ms, lines, screen, styles, until, settle_ms)

def click(sid=None, target=(1, 1), btn=0, **poll_kw):
    "Click `sid`'s pane at a 1-based `(col,row)`, or on a str/regex located on its screen"
    return pane(sid).click(target, btn, **poll_kw)

def wheel(sid=None, n=3, at=(1, 1), **poll_kw):
    "Send `n` SGR wheel events to `sid`'s pane (up for positive `n`, down for negative)"
    return pane(sid).wheel(n, at, **poll_kw)

def display(sid=None, lines=80):
    "Capture the last `lines` of `sid`'s pane"
    return pane(sid).display(lines)

def screen(sid=None, styles=False):
    "The visible viewport of `sid`'s pane (rows below the cursor included)"
    return pane(sid).screen(styles)

# %% ../nbs/01_bg.ipynb #f723b963
def close(sid=None):
    "Kill the session owning `sid`'s pane"
    Session.fetch(pane(sid).fmt('#{session_id}')).kill()  # by id: name lookups can prefix-match a sibling

def managed_sessions():
    "Sessions created by `start_session`"
    return Sessions(s for s in tmux() if _tmux('show-options','-qv','-t',s.id,'@fastmux_pane_id'))
